from __future__ import annotations

import sqlite3
import subprocess
import sys
from pathlib import Path

from evalmerge.pipeline import dump_results, ingest, report
from generate_fixtures import generate


def fetch_all(db_path: Path, sql: str) -> list[sqlite3.Row]:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    try:
        return list(conn.execute(sql))
    finally:
        conn.close()


def warning_counts(db_path: Path) -> dict[str, int]:
    return {
        row["rule"]: row["count"]
        for row in fetch_all(
            db_path,
            "SELECT rule, COUNT(*) AS count FROM warnings GROUP BY rule ORDER BY rule",
        )
    }


def prepared(tmp_path: Path) -> tuple[Path, Path]:
    fixtures = tmp_path / "fixtures"
    db_path = tmp_path / "evalmerge.sqlite"
    generate(fixtures)
    ingest(fixtures, db_path)
    return fixtures, db_path


def test_ingests_all_formats_and_normalizes_rows(tmp_path: Path) -> None:
    _, db_path = prepared(tmp_path)
    rows = dump_results(db_path)

    by_source = {}
    for row in rows:
        by_source[row[1]] = by_source.get(row[1], 0) + 1
    assert by_source == {"a": 8, "b": 5, "c": 4}

    models = {row[2] for row in rows}
    assert "google/gemma-2-2b" in models
    assert "other-model" in models

    row_a001 = next(row for row in rows if row[0] == "a-001")
    assert row_a001[4] == 0.875
    assert row_a001[6] == "2026-05-01T12:00:00Z"

    row_a002 = next(row for row in rows if row[0] == "a-002")
    assert row_a002[4] == 0.72
    assert row_a002[6] == "2026-05-01T12:30:00Z"

    row_c001 = next(row for row in rows if row[0] == "c-001")
    assert row_c001[4] == 0.82
    assert row_c001[6] == "2026-05-03T00:00:00Z"


def test_planted_warning_counts_and_clamping(tmp_path: Path) -> None:
    _, db_path = prepared(tmp_path)
    assert warning_counts(db_path) == {
        "invalid_meta_json": 2,
        "missing_score": 2,
        "score_out_of_range": 2,
        "unknown_unit": 2,
        "unparseable_timestamp": 2,
    }

    clamped = {
        row["run_id"]: row["score"]
        for row in fetch_all(
            db_path,
            "SELECT run_id, score FROM results WHERE run_id IN ('a-003', 'a-007')",
        )
    }
    assert clamped == {"a-003": 1.0, "a-007": 0.0}

    extras = {
        row["run_id"]: row["raw_extra"]
        for row in fetch_all(
            db_path,
            "SELECT run_id, raw_extra FROM results WHERE run_id IN ('a-005', 'a-008', 'a-006', 'a-009')",
        )
    }
    assert extras["a-005"].startswith('{"meta":')
    assert extras["a-008"].startswith('{"meta":')
    assert extras["a-006"] == "[1,2]"
    assert extras["a-009"] == "[3,4]"


