def parse_score(
    value: Any,
    unit: str | None,
    state: IngestState,
    source: str,
    path: Path,
    row_ref: str,
) -> float | None:
    if value is None or str(value).strip() == "":
        warn(state, SKIP_MISSING_SCORE, source, path, row_ref, "missing score")
        return None
    raw = str(value).strip()
    try:
        if raw.endswith("%"):
            score = float(raw[:-1]) / 100.0
        elif unit == "percent":
            score = float(raw) / 100.0
        elif unit == "fraction" or unit is None:
            score = float(raw)
        else:
            numeric = float(raw)
            warn(
                state,
                WARN_UNKNOWN_UNIT,
                source,
                path,
                row_ref,
                f"unknown score unit {unit!r}",
            )
            score = numeric / 100.0 if numeric > 1 else numeric
    except ValueError:
        warn(state, SKIP_MISSING_SCORE, source, path, row_ref, f"invalid score {raw!r}")
        return None

    if score < 0.0 or score > 1.0:
        warn(
            state,
            WARN_SCORE_OUT_OF_RANGE,
            source,
            path,
            row_ref,
            f"score {score!r} outside [0, 1]",
        )
        score = max(0.0, min(1.0, score))
    return score


def parse_timestamp(raw: str) -> str | None:
    raw = raw.strip()
    formats = ("%Y-%m-%dT%H:%M:%SZ", "%m/%d/%Y %H:%M")
    for fmt in formats:
        try:
            return rfc3339(datetime.strptime(raw, fmt).replace(tzinfo=timezone.utc))
        except ValueError:
            pass
    return None


def parse_epoch(value: Any) -> str | None:
    try:
        epoch = float(value)
    except (TypeError, ValueError):
        return None
    if epoch > 10_000_000_000:
        epoch /= 1000.0
    try:
        return rfc3339(datetime.fromtimestamp(epoch, tz=timezone.utc))
    except (OverflowError, OSError, ValueError):
        return None


def parse_date(raw: str) -> str | None:
    try:
        dt = datetime.strptime(raw.strip(), "%Y-%m-%d").replace(tzinfo=timezone.utc)
    except ValueError:
        return None
    return rfc3339(dt)


